export function EcosystemSection() {
  return (
    <section
      id="ecosystem"
      className={styles.ecosystemSection}
      aria-label="Supported Ecosystems"
    >
      <div className={styles.sectionHeader}>
        <h2 className={`${styles.sectionTitle} eco-title`}>
          Native Ecosystem Support
        </h2>
        <p className={`${styles.sectionDesc} eco-desc`}>
          Inspects native lockfiles and dependencies across 7+ modern stacks
          without running untrusted scripts.
        </p>
      </div>

      <div className={styles.ecosystemCardsGrid}>
        {ECOSYSTEMS.map((item) => (
          <div key={item.name} className={`${styles.ecosystemCard} eco-card`}>
            <div className={styles.ecoCardHeader}>
              <span
                className={styles.ecoIcon}
                style={{ borderColor: item.color, color: item.color }}
              >
                {item.renderIcon()}
              </span>
              <div>
                <h3 className={styles.ecoName}>{item.name}</h3>
                <span className={styles.ecoBadge}>{item.badge}</span>
              </div>
            </div>

            <div className={styles.ecoManifestTag}>
              <code>{item.manifest}</code>
            </div>

            <p className={styles.ecoDesc}>{item.desc}</p>
          </div>
        ))}
      </div>
    </section>
  );
}
